def _parse_time(value):
    if isinstance(value, time):
        return value
    try:
        return time.fromisoformat(value)
    except (TypeError, ValueError):
        return None


def renumber_mislabeled_slots(apps, schema_editor):
    Semester = apps.get_model('api', 'Semester')
    TimeSlot = apps.get_model('api', 'TimeSlot')

    updated = 0
    for semester in Semester.objects.all():
        time_schedule = _semester_config(semester).get('time_schedule') or []
        period_by_start = {}
        for index, entry in enumerate(time_schedule, start=1):
            if not isinstance(entry, (list, tuple)) or not entry:
                continue
            start = _parse_time(entry[0])
            if start is None:
                continue
            period_by_start.setdefault(start, index)

        if not period_by_start:
            continue

        for slot in TimeSlot.objects.filter(semester_id=semester.pk):
            expected = period_by_start.get(slot.start_time)
            if expected is not None and slot.period_number != expected:
                TimeSlot.objects.filter(pk=slot.pk).update(period_number=expected)
                updated += 1

    print(f"0021: renumbered {updated} mislabeled time slot(s)")


def dedupe_copies(apps, schema_editor):
    TimeSlot = apps.get_model('api', 'TimeSlot')
    Lesson = apps.get_model('api', 'Lesson')

